fn reverse(s: Vec<i8>) -> Vec<i8> {
    let n = s.len();
    let mut rev = Vec::with_capacity(n); // Create a new vector with the same capacity as the input

    for i in (0..n).rev() { // Iterate from n-1 to 0
        rev.push(s[i]); // Push elements in reverse order
    }

    rev // Return the reversed vector
}